def fewestSameUnion(intervals):
    ivs = sorted(intervals)
    n = len(ivs)
    i = 0
    count = 0
    while i < n:
        reach = ivs[i][0]
        while True:
            best = reach
            while i < n and ivs[i][0] <= reach:
                if ivs[i][1] > best:
                    best = ivs[i][1]
                i += 1
            if best == reach:
                break
            count += 1
            reach = best
    return count
